/* @lc app=leetcode id=4008 lang=kotlin */ class Solution { fun minInitialStrength(monsters: IntArray, boosts: Array<IntArray>): Long = monsters.size.let { n -> LongArray(n + 1).also { d -> boosts.forEach { (l, r, v) -> d.set(l, d[l] + v).also { d[r + 1] -= v.toLong() } } }.runningFold(0L) { a, b -> a + b }.drop(1).let { bonus -> generateSequence(0L to monsters.sumOf { it.toLong() }) { (lo, hi) -> ((lo + hi) / 2).let { mid -> if (monsters.indices.fold(mid) { cur, i -> if (cur < 0) cur else if (cur + bonus[i] >= monsters[i]) maxOf(0L, cur - monsters[i]) else -1L } >= 0) lo to mid else mid + 1 to hi } }.first { it.first >= it.second }.first } } }